BEGIN;
SELECT set_config('test.actor','20000000-0000-0000-0000-000000000001',true);
SELECT set_config('test.pilot','true',true);
SELECT set_config('test.pilot_write','true',true);
UPDATE private_isg.rollout SET read_enabled=true,write_enabled=true;
UPDATE private_isg.module_registry SET read_enabled=true,write_enabled=true;
DO $$ DECLARE p uuid; r jsonb; answer jsonb; rows_ jsonb; BEGIN
 SELECT id INTO p FROM private_isg.employees WHERE company_id='10000000-0000-0000-0000-000000000001' AND NOT is_archived LIMIT 1;
 r:=public.isg_pilot_process_mutate_v1('10000000-0000-0000-0000-000000000001','save',gen_random_uuid(),gen_random_uuid(),jsonb_build_object('kind','personnel_certificate','values',jsonb_build_object('employee_id',p,'certificate_kind','custom','title','Takip testi','issued_on',current_date-365,'valid_until',current_date+10,'due_override',true)));
 answer:=public.isg_pilot_followup_v1('10000000-0000-0000-0000-000000000001','soon','Takip testi',0);
 IF jsonb_array_length(answer->'rows')<>1 OR answer->'rows'->0->>'status'<>'soon' THEN RAISE EXCEPTION 'source not tracked %',answer; END IF;
 IF NOT EXISTS(SELECT 1 FROM private_isg.notice_rows('20000000-0000-0000-0000-000000000001',NULL) WHERE kind='personnel_certificate' AND record_id=(r->>'id')::uuid) THEN RAISE EXCEPTION 'certificate notice missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.isg_pilot_module_tracking_v2(NULL)->'rows') x WHERE x->>'kind'='personnel_certificate' AND (x->>'total')::int=1) THEN RAISE EXCEPTION 'company/statistics tracking missing'; END IF;
 PERFORM public.isg_pilot_process_mutate_v1('10000000-0000-0000-0000-000000000001','delete',gen_random_uuid(),gen_random_uuid(),jsonb_build_object('kind','personnel_certificate','id',r->>'id','expected',r->>'expected'));
 IF jsonb_array_length(public.isg_pilot_followup_v1(NULL,NULL,'Takip testi',0)->'rows')<>0 THEN RAISE EXCEPTION 'deleted source remains'; END IF;
 PERFORM set_config('test.actor','20000000-0000-0000-0000-000000000002',true);
 BEGIN PERFORM public.isg_pilot_followup_v1('10000000-0000-0000-0000-000000000001');RAISE EXCEPTION 'other owner followup'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM<>'ACCESS_DENIED' THEN RAISE; END IF; END;
 RAISE NOTICE 'ok unified source tracking / filtering / certificate notices / company and statistics parity / deletion / owner isolation';
END $$;
ROLLBACK;
